WITH flattened_attrs AS (SELECT id, service, log_ts, FROM_JSON(payload_json, 'STRUCT<user: STRUCT<id: INT, tier: STRING>, duration: DOUBLE, retries: INT, tags: ARRAY<STRING>>').user.tier AS tier, FROM_JSON(payload_json, 'STRUCT<user: STRUCT<id: INT, tier: STRING>, duration: DOUBLE, retries: INT, tags: ARRAY<STRING>>').duration AS duration_sec, COALESCE(context['trace'], 'direct') AS trace_or_default, SHIFTRIGHT(status_code, 2) AS status_code_high, GET_JSON_OBJECT(payload_json, '$.duration') AS duration_text FROM app_logs WHERE service <> 'checkout') SELECT CASE WHEN duration_sec >= 3.8 THEN 'LARGE' ELSE 'SMALL' END AS duration_sec_tier, CASE WHEN status_code_high >= 2 THEN 'HIGH' ELSE 'LOW' END AS status_code_high_tier, COUNT(*) FILTER (WHERE service = 'auth') AS auth_rows, SUM(duration_sec) FILTER (WHERE service = 'billing') AS billing_total_duration_sec FROM flattened_attrs GROUP BY CUBE (CASE WHEN duration_sec >= 3.8 THEN 'LARGE' ELSE 'SMALL' END, CASE WHEN status_code_high >= 2 THEN 'HIGH' ELSE 'LOW' END);
